"""Build self-contained per-run inspectors; 32MB evidence never embedded in landing.
Each run independently opens through file:// with no fetch dependencies.
"""
from pathlib import Path
import json,html,sys,hashlib
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from build_laminar_pages import shell
P=ROOT/'projects/laminar-lab';E=html.escape

JS=r'''
const DATA=DATA_LITERAL;let section='policies',page=0,query='';const $=id=>document.getElementById(id);
function records(){if(section==='audit')return [DATA.audit,DATA.before_restart||{},...DATA.tamper_checks];return DATA[section]||[]}
function setDetails(x){$('selected-record').textContent=JSON.stringify(x,null,2)}
function draw(){const all=records().filter(x=>JSON.stringify(x).toLowerCase().includes(query));const max=Math.max(1,Math.ceil(all.length/15));page=Math.min(page,max-1);$('status').textContent=`${all.length} records · page ${page+1}/${max}`;$('previous').disabled=page===0;$('next').disabled=page>=max-1;const tbody=document.createElement('tbody');all.slice(page*15,page*15+15).forEach((x,i)=>{const tr=document.createElement('tr'),num=document.createElement('td'),desc=document.createElement('td'),ctrl=document.createElement('td'),b=document.createElement('button');num.textContent=page*15+i+1;desc.textContent=section==='policies'?`version ${x.version}; Adam step ${x.optimizer.step}`:section==='work'?`group ${x.gid}; policy ${x.policy_version}; ${x.status}; ${x.state.tokens_written} saved tokens`:section==='events'?`${x.seq}; session ${x.session}; ${x.kind}`:section==='sessions'?`session ${x.id}; resume version ${x.resume_version}`:'Verified contract';b.textContent='Inspect';b.onclick=()=>setDetails(x);ctrl.appendChild(b);tr.append(num,desc,ctrl);tbody.appendChild(tr)});$('table-body').replaceChildren(...tbody.children);setDetails(all[page*15]||{message:'No matching record'})}
function timeline(){const ev=DATA.events.filter(e=>['session_start','resume_prefix','learner_commit','reserve','ready'].includes(e.kind)),colors={session_start:'#d18a42',resume_prefix:'#b57156',learner_commit:'#327895',reserve:'#bbb',ready:'#799b8f'};const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 900 220');svg.setAttribute('role','img');svg.setAttribute('aria-label','Real event sequence across restart sessions');const background=document.createElementNS(svg.namespaceURI,'rect');background.setAttribute('width','900');background.setAttribute('height','220');background.setAttribute('fill','white');svg.appendChild(background);ev.forEach((e,i)=>{const r=document.createElementNS(svg.namespaceURI,'rect');r.setAttribute('x',40+i*820/Math.max(ev.length-1,1));r.setAttribute('y',e.kind==='learner_commit'?70:125);r.setAttribute('width',Math.max(2,790/ev.length));r.setAttribute('height',e.kind==='session_start'?65:28);r.setAttribute('fill',colors[e.kind]);const t=document.createElementNS(svg.namespaceURI,'title');t.textContent=`sequence ${e.seq} / session ${e.session}: ${e.kind}`;r.appendChild(t);svg.appendChild(r)});const label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x','40');label.setAttribute('y','200');label.setAttribute('font-size','12');label.textContent='x = ordered recorded events, NOT uniform wall time; blue = commit, orange = restart; inspect full events below.';svg.appendChild(label);$('timeline').replaceChildren(svg)}
$('section').onchange=e=>{section=e.target.value;page=0;draw()};$('query').oninput=e=>{query=e.target.value.toLowerCase();page=0;draw()};$('previous').onclick=()=>{page--;draw()};$('next').onclick=()=>{page++;draw()};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(DATA,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='laminar-live-run.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500)};$('summary').textContent=JSON.stringify({run:DATA.run,summary:DATA.summary,audit:DATA.audit},null,2);timeline();draw();
'''
def table(summary):
 fields=['name','fault','capacity','max_consume_staleness']
 header='<th>Run</th><th>Fault</th><th>Capacity</th><th>Max staleness</th><th>Consumed / discarded</th><th>Sessions</th><th>Evidence</th>'
 rows=[]
 for r in summary['runs']:
  cells=''.join('<td>'+E(str(r[k]))+'</td>' for k in fields)+f'<td>{r["counts"]["consumed"]} / {r["counts"]["discarded"]}</td><td>{r["audit"]["sessions"]}</td><td><a href="live-evidence/{E(r["name"])}.html">Inspect →</a></td>';rows.append('<tr>'+cells+'</tr>')
 return '<div class="table-scroll"><table class="paper-table"><thead><tr>'+header+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'

def section(summary,boundaries):
 return '<section class="project-section"><h2>Live Async RL &amp; Durable Recovery</h2><p>上一版将实时异步与确定序恢复分开，本轮把它们接入同一实际运行的coordinator。四个producer逐token生成，SQLite持久化prefix和RNG；训练读取FIFO完成组，真实Adam四次更新；一次事务绑定策略快照、Adam状态和唯一消费账本。每轨迹绑定生成时版本，重启不改成新权重。</p><p>20组主矩阵包含12次真实进程退出；另4次重点记录“退出之后、重启之前”的数据库。每运行20次已提交更新、120组消费，主矩阵400次和边界回归80次更新全部逐步独立重放。保存奖励manifest并由另一个函数按原prompt和actions复算奖励；5种篡改探针检查reward、logprob、version、event hash与Adam step。</p>'+table(summary)+'<p class="caption">本表是系统正确性对照，不横比模型质量。真实调度次序不可重复，fault run不应宣称与未中断基线相同最终模型；固定任务probe已有prompt overlap，不代表大模型能力。Hash链是篡改痕迹，不是签名或可信第三方验收。</p><h3>Crash boundaries</h3><p>在提交前或事务内退出，数据库停在version4、24个消费组、Adam step16；提交后退出停在version5、30个消费组、Adam step20。重启时pending batch沿原顺序重新优化，已经提交的组不会再消费；采样prefix从已存RNG继续生成，不重算prefix token。</p><ul>'+''.join('<li>'+E(r['fault'])+' · <a href="live-evidence/boundary-'+E(r['fault'])+'.html">View pre-restart database snapshot →</a></li>' for r in boundaries['runs'])+'</ul><h3>What this does not prove</h3><p>整机coordinator进程中断恢复，不是单独worker机器故障或多机exactly-once。仍使用toy MLP，没有语言模型LoRA-RL、UCX、真实GPU KV迁移或集群吞吐；容量6等于一batch使异步退化为近似同步，不能把消除陈旧度视作免费收益。</p></section>'

def build():
 out=P/'live-evidence';out.mkdir(exist_ok=True);summary=json.loads((P/'artifacts/live-system/summary.json').read_text());bounds=json.loads((P/'artifacts/live-crash-boundaries/summary.json').read_text());count=0
 for dirname,prefix in [('live-system',''),('live-crash-boundaries','boundary-')]:
  for path in sorted((P/'artifacts'/dirname).glob('*.json')):
   if path.name in ['protocol.json','summary.json'] or path.name.endswith('-config.json'):continue
   d=json.loads(path.read_text());name=prefix+path.stem;payload=json.dumps(d,separators=(',',':'),ensure_ascii=False,allow_nan=False).replace('</',r'<\/')
   body='<section class="project-section"><h2>'+E(name)+'</h2><p>真实本地异步运行证据；这里回读冻结数据，不在网页假训练。<a href="../live-study.html">All live runs →</a></p><pre id="summary"></pre><div id="timeline"></div><div class="explorer-controls"><label>Evidence type<select id="section"><option value="policies">Policy / Adam checkpoints</option><option value="work">Completed and partial trajectories</option><option value="events">Append-only actual events</option><option value="sessions">Restart sessions</option><option value="audit">Independent checks and tamper probes</option></select></label><label>Filter<input id="query" placeholder="version / gid / session"></label><button id="download">Export full JSON</button></div><p id="status"></p><button id="previous">Previous</button> <button id="next">Next</button><div class="table-scroll"><table class="paper-table"><thead><tr><th>#</th><th>Original record</th><th>Open</th></tr></thead><tbody id="table-body"></tbody></table></div><pre id="selected-record"></pre></section><script>'+JS.replace('DATA_LITERAL',payload)+'</script>'
   page=shell('Laminar-Lab | '+name,body).replace('href="../../index.html','href="../../../index.html').replace('href="project.html"','href="../project.html"').replace('href="evidence.html"','href="../evidence.html"');(out/(name+'.html')).write_text(page);count+=1
 body=section(summary,bounds);page=shell('Laminar-Lab | Live Async Recovery',body);(P/'live-study.html').write_text(page)
 project=P/'project.html';text=project.read_text();marker='<section class="project-section" id="live-study"><h2>Live Async Training &amp; Recovery</h2><p>新增实时异步训练、逐token prefix/RNG持久化、Adam状态与消费原子提交；20组矩阵与4个边界回归包含16次真实进程中断。已独立重放480次提交更新，逐条复算奖励与行为概率。</p><p><a class="resource" href="live-study.html">Live Study / 完整证据</a></p><p class="caption">单机coordinator恢复，不是分布式exactly-once或语言大模型训练；hash链不等于签名。</p></section>'
 if 'id="live-study"' not in text:project.write_text(text.replace('<main>','<main>'+marker,1))
 checks={str(f.relative_to(P)):hashlib.sha256(f.read_bytes()).hexdigest() for f in P.rglob('*') if f.is_file() and '__pycache__' not in f.parts and f.name!='checksums.json'};(P/'artifacts/checksums.json').write_text(json.dumps(checks,indent=2));print('Built',count,'self-contained live inspectors; landing remains compact')
if __name__=='__main__':build()
